 private int userId,matchScore; private String fullName,email,departmentName,positionName,levelName,matchReason;
 public int getUserId(){return userId;} public void setUserId(int v){userId=v;} public int getMatchScore(){return matchScore;} public void setMatchScore(int v){matchScore=v;} public String getFullName(){return fullName;} public void setFullName(String v){fullName=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getDepartmentName(){return departmentName;} public void setDepartmentName(String v){departmentName=v;} public String getPositionName(){return positionName;} public void setPositionName(String v){positionName=v;} public String getLevelName(){return levelName;} public void setLevelName(String v){levelName=v;} public String getMatchReason(){return matchReason;} public void setMatchReason(String v){matchReason=v;}
